{
  "findings": [
    {
      "check_id": "CKV_GCP_26",
      "title": "VPC Flow Logs are not enabled",
      "resource": "google_compute_subnetwork.data_subnet",
      "severity": "MEDIUM",
      "explanation": "The subnet has no log_config block, so network flow telemetry is unavailable for detecting suspicious traffic and supporting security investigations."
    }
  ],
  "patched_code": "resource "google_compute_subnetwork" "data_subnet" {
  name                     = "hipaa-compliant-patient-portal-subnet-data"
  ip_cidr_range            = "10.0.3.0/24"
  region                   = var.region
  network                  = google_compute_network.hipaa_vpc.id
  private_ip_google_access = true

  log_config {
    aggregation_interval = "INTERVAL_5_SEC"
    flow_sampling        = 0.5
    metadata             = "INCLUDE_ALL_METADATA"
  }
}
",
  "fix_summary": "Enabled VPC Flow Logs for the subnet with five-second aggregation, 50% flow sampling, and metadata inclusion."
}
